#!/usr/bin/env bash
# @@REPO@@ — per-repo validation gate (stack: @@STACK@@).
# Generated by tools/validate/generate.sh. Edit freely afterwards; the generator
# will not overwrite this file without --force.
#
#   quick   seconds. Configure + static analysis. No compile.
#   full    minutes. Build and test.
set -uo pipefail
# shellcheck source=lib/validate-lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/validate-lib.sh"

TIER="$(tier_or_die "${1:-quick}")"

# --- quick -----------------------------------------------------------------

assert "CMakeLists.txt present" 'test -f CMakeLists.txt'

check "cmake configure parses" "cmake ninja" \
  'cmake -GNinja -S . -B build/native >/dev/null'

# The leaf Makefiles treat analysers as best-effort and exit 0 when they are
# missing, which reports "clean" for a run that analysed nothing. Require the
# tool so an absent analyser is BLOCKED instead.
check "cppcheck static analysis" "cppcheck cmake ninja" 'make cppcheck'

check "clang-format clean" "clang-format" \
  'find src -name "*.cc" -o -name "*.cpp" -o -name "*.h" 2>/dev/null \
     | xargs -r clang-format --dry-run --Werror'

[ "$TIER" = "quick" ] && { report "$TIER"; exit $?; }

# --- full ------------------------------------------------------------------

check "builds clean" "cmake ninja" 'make build'
check "tests" "cmake ninja ctest" 'make test'

report "$TIER"
